from collections import deque

class Solution:
    def deckRevealedIncreasing(self, deck: list[int]) -> list[int]:
        deck.sort()
        n = len(deck)
        q = deque(range(n))
        res = [0] * n
        for card in deck:
            res[q.popleft()] = card
            if q:
                q.append(q.popleft())
        return res

class Solution {
public:
    vector<int> deckRevealedIncreasing(vector<int>& deck) {
        sort(deck.begin(), deck.end());
        int n = deck.size();
        deque<int> q;
        for (int i = 0; i < n; ++i) q.push_back(i);
        vector<int> res(n);
        for (int card : deck) {
            res[q.front()] = card;
            q.pop_front();
            if (!q.empty()) {
                q.push_back(q.front());
                q.pop_front();
            }
        }
        return res;
    }
};

class Solution {
    public int[] deckRevealedIncreasing(int[] deck) {
        Arrays.sort(deck);
        int n = deck.length;
        Deque<Integer> q = new LinkedList<>();
        for (int i = 0; i < n; i++) q.add(i);
        int[] res = new int[n];
        for (int card : deck) {
            res[q.pollFirst()] = card;
            if (!q.isEmpty()) {
                q.addLast(q.pollFirst());
            }
        }
        return res;
    }
}

var deckRevealedIncreasing = function(deck) {
    deck.sort((a, b) => a - b);
    const n = deck.length;
    const q = Array.from({ length: n }, (_, i) => i);
    const res = new Array(n);
    for (const card of deck) {
        res[q.shift()] = card;
        if (q.length > 0) {
            q.push(q.shift());
        }
    }
    return res;
};
